// === Tab: mySketch.js ===
let cnv;
let particles = [];
let currentParticleCount = 10000;

// Variables de los controladores UI
let nSlider, mSlider, aSlider, bSlider, vibSlider, countSlider;
let sizeSlider, deformSlider; 
let bgColorPicker, ptColorPicker, ratioSelect;

// Variables de física (de la referencia)
const pi = 3.1415926535;
let minWalk = 0.002; 

// Ecuación exacta de Chladni de la página de referencia
const chladni = (x, y, a, b, m, n) => 
  a * sin(pi * n * x) * sin(pi * m * y) + b * sin(pi * m * x) * sin(pi * n * y);

function setup() {
  cnv = createCanvas(800, 800);
  cnv.style('z-index', '-1'); 
  cnv.style('position', 'absolute');

  let startY = 20;
  let gap = 35;

  // --- 1. CONTROLES DE FRECUENCIA Y FÍSICA ---
  nSlider = createMyControl("Frecuencia (n)", startY, 1, 16, 4, 1);
  mSlider = createMyControl("Frecuencia (m)", startY + gap*1, 1, 16, 8, 1);
  aSlider = createMyControl("Amplitud (a)", startY + gap*2, -2, 2, 1, 0.1);
  bSlider = createMyControl("Amplitud (b)", startY + gap*3, -2, 2, 1, 0.1);
  // La fuerza de vibración la ajustamos a los valores reales de la referencia (0.01 a 0.1)
  vibSlider = createMyControl("Fuerza Vibración", startY + gap*4, 0.01, 0.1, 0.02, 0.01);
  countSlider = createMyControl("Cant. Semillas", startY + gap*5, 1000, 30000, 20000, 1000);

  // --- 2. CONTROLES DE SEMILLAS ---
  sizeSlider = createMyControl("Tamaño (mm)", startY + gap*6.5, 1, 15, 4, 0.5);
  deformSlider = createMyControl("Deformación", startY + gap*7.5, 0, 0.9, 0.5, 0.1); 

  let nextY = startY + gap * 9;

  // --- 3. CONTROLES DE COLOR ---
  createUILabel("Color de Fondo:", 20, nextY);
  bgColorPicker = createColorPicker('#141414').position(140, nextY - 5);

  nextY += gap;
  createUILabel("Color Semillas:", 20, nextY);
  ptColorPicker = createColorPicker('#F0E6C8').position(140, nextY - 5);

  nextY += gap;

  // --- 4. CONTROLES DE FORMATO ---
  createUILabel("Formato Lienzo:", 20, nextY);
  ratioSelect = createSelect().position(140, nextY);
  ratioSelect.option('1:1 (Cuadrado)', '1:1');
  ratioSelect.option('16:9 (Pantalla/PC)', '16:9');
  ratioSelect.option('9:16 (Móvil/Stories)', '9:16');
  ratioSelect.option('4:3 (Clásico H)', '4:3');
  ratioSelect.option('3:4 (Clásico V)', '3:4');
  ratioSelect.option('3:2 (Fotografía H)', '3:2');
  ratioSelect.option('2:3 (Fotografía V)', '2:3');
  ratioSelect.changed(applyAspectRatio);

  nextY += gap + 15;

  // --- INSTRUCCIONES ---
  let helpText = createDiv("<b>Exportar JPEG:</b> Pulsa 'J'<br><b>Reiniciar Arena:</b> Pulsa 'R'");
  helpText.position(20, nextY);
  helpText.style('color', 'white');
  helpText.style('font-family', 'sans-serif');
  helpText.style('font-size', '14px');
  helpText.style('text-shadow', '1px 1px 3px black');
  helpText.style('line-height', '1.5');

  applyAspectRatio();
}

function draw() {
  background(bgColorPicker.value());

  let n = nSlider.value();
  let m = mSlider.value();
  let a = aSlider.value();
  let b = bSlider.value();
  let v = vibSlider.value();

  let baseSize = sizeSlider.value();
  let deformation = deformSlider.value();

  // Controlar cambio de número de partículas
  if (countSlider.value() !== currentParticleCount) {
    currentParticleCount = countSlider.value();
    initParticles(currentParticleCount);
  }

  stroke(ptColorPicker.value());
  strokeCap(ROUND); // Esencial para que parezcan semillas (bordes redondeados)

  for (let i = 0; i < particles.length; i++) {
    let p = particles[i];

    // --- FÍSICA DE LA REFERENCIA ---
    let eq = chladni(p.x, p.y, a, b, m, n);
    let stochasticAmplitude = v * abs(eq);

    if (stochasticAmplitude <= minWalk) stochasticAmplitude = minWalk;

    p.x += random(-stochasticAmplitude, stochasticAmplitude);
    p.y += random(-stochasticAmplitude, stochasticAmplitude);

    // Rebote/Límites internos (0 a 1)
    if (p.x <= 0) p.x = 0;
    if (p.x >= 1) p.x = 1;
    if (p.y <= 0) p.y = 0;
    if (p.y >= 1) p.y = 1;

    // --- DIBUJO ---
    // Mapeamos el espacio 0-1 a las dimensiones de la pantalla actual
    let xOff = p.x * width;
    let yOff = p.y * height;

    // Calculamos la forma de la semilla
    let actualSize = baseSize * p.sizeMod; 
    let thickness = actualSize * (1 - deformation); 
    if(thickness < 1) thickness = 1; // Para que no desaparezcan del todo al deformar al máximo

    strokeWeight(thickness);

    let dx = cos(p.angle) * (actualSize - thickness) / 2;
    let dy = sin(p.angle) * (actualSize - thickness) / 2;

    line(xOff - dx, yOff - dy, xOff + dx, yOff + dy);
  }
}

// --- FUNCIONES AUXILIARES ---

function initParticles(num) {
  particles = [];
  for (let i = 0; i < num; i++) {
    particles.push({
      x: random(0, 1),      // Ahora la posición nativa es de 0 a 1 (referencia)
      y: random(0, 1),
      angle: random(TWO_PI), 
      sizeMod: random(0.7, 1.3) 
    });
  }
}

function applyAspectRatio() {
  let ratioStr = ratioSelect.value().split(' ')[0];
  let parts = ratioStr.split(':');
  let rw = parseFloat(parts[0]);
  let rh = parseFloat(parts[1]);

  let margin = 40;
  let maxW = windowWidth - margin;
  let maxH = windowHeight - margin;

  let scaleW = maxW / rw;
  let scaleH = maxH / rh;
  let scaleRatio = min(scaleW, scaleH);

  let finalW = floor(rw * scaleRatio);
  let finalH = floor(rh * scaleRatio);

  resizeCanvas(finalW, finalH);

  cnv.style('left', ((windowWidth - finalW) / 2) + 'px');
  cnv.style('top', ((windowHeight - finalH) / 2) + 'px');

  initParticles(currentParticleCount);
}

function createMyControl(name, y, minVal, maxVal, startVal, stepVal) {
  let label = createUILabel(name + ": " + startVal, 20, y);
  let s = createSlider(minVal, maxVal, startVal, stepVal);
  s.position(180, y);
  s.style('width', '150px');

  s.input(() => {
    label.html(name + ": " + s.value());
  });
  return s;
}

function createUILabel(texto, x, y) {
  var label = createSpan(texto).position(x, y);
  label.style('color', 'white');
  label.style('font-family', 'sans-serif');
  label.style('font-size', '14px');
  label.style('text-shadow', '1px 1px 3px black');
  return label;
}

function keyPressed() {
  if (key === 'j' || key === 'J') {
    let resolutionName = ratioSelect.value().split(' ')[0].replace(':', 'x');
    saveCanvas(cnv, 'Chladni_Semillas_' + resolutionName, 'jpg');
  }
  if (key === 'r' || key === 'R') {
    initParticles(currentParticleCount);
  }
}

function windowResized() {
  applyAspectRatio();
}

